def _manifests(output: Path) -> list[dict[str, Any]]:
    directory = _root(output) / "manifests"
    return [json_load(path) for path in sorted(directory.glob("*.json"))] if directory.is_dir() else []

def _manifest(output: Path, reference_id: str) -> tuple[Path, dict[str, Any]]:
    path = _root(output) / "manifests" / f"{reference_id}.json"
    if not path.is_file():
        raise CkbError(f"reference does not exist: {reference_id}")
    return path, json_load(path)

def _validate_output(output: Path) -> Path:
    output = output.resolve()
    if not (output / "state.json").is_file() or not (output / "human").is_dir() or not (output / "markdown").is_dir():
        raise CkbError(f"completed CKB Markdown output is required: {output}")
    return output

def _validate_license(value: str) -> str:
    normalized = value.strip()
    if normalized.casefold() in INVALID_LICENSE_VALUES:
        raise CkbError("reference license must be an explicit SPDX identifier or a concrete user-provided license statement")
    return normalized

def _decode_source(source: Path) -> tuple[bytes, str, str]:
    suffix = source.suffix.casefold()
    if suffix not in SUPPORTED_SUFFIXES:
        raise CkbError("reference source must be a local UTF-8 .md or .txt file")
    raw = source.read_bytes()
    if not raw or len(raw) > MAX_REFERENCE_BYTES:
        raise CkbError(f"reference source must contain 1..{MAX_REFERENCE_BYTES} bytes")
    try:
        text = raw.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise CkbError(f"reference source must be valid UTF-8: {exc}") from exc
    if "\x00" in text:
        raise CkbError("reference source contains a NUL byte and is not treated as text")
    return raw, text.replace("\r\n", "\n").replace("\r", "\n"), SUPPORTED_SUFFIXES[suffix]

def _set_marker(output: Path, status: str, payload: dict[str, Any]) -> None:
    root = _root(output)
    for name in (".pending-agent-review", ".failed", ".complete"):
        (root / name).unlink(missing_ok=True)
    name = ".complete" if status == "passed" else ".pending-agent-review" if status == "pending-agent-review" else ".failed"
    json_write(root / name, payload)

def write_reference_review_template(output: Path, reference_id: str, target: Path) -> dict[str, Any]:
    output = _validate_output(output)
    _path, manifest = _manifest(output, reference_id)
    source = Path(str(manifest["review_template"]))
    target = target.resolve()
    if target.exists():
        raise CkbError(f"reference review target already exists: {target}")
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, target)
    return {"schema_version": 1, "status": "written", "reference_id": reference_id, "review": str(target)}

def _source_lines(manifest: dict[str, Any]) -> list[str]:
    raw = Path(str(manifest["source_file"])).read_bytes()
    if __import__("hashlib").sha256(raw).hexdigest() != manifest.get("source_sha256"):
        raise CkbError(f"reference source drifted: {manifest['reference_id']}")
    return raw.decode("utf-8-sig").replace("\r\n", "\n").replace("\r", "\n").split("\n")

def _validate_review(manifest: dict[str, Any], review: dict[str, Any]) -> None:
    if review.get("schema_version") != REFERENCE_SCHEMA_VERSION:
        raise CkbError("reference review schema_version mismatch")
    if review.get("reference_id") != manifest["reference_id"] or review.get("status") != "agent-reviewed":
        raise CkbError("reference review must target one manifest and use status agent-reviewed")
    if review.get("source_sha256") != manifest["source_sha256"]:
        raise CkbError("reference review source_sha256 does not match the preserved source")
    if not contains_chinese_narrative(review.get("summary_zh")):
        raise CkbError("reference summary_zh must contain useful Simplified-Chinese narrative")
    claims = review.get("claims")
    if not isinstance(claims, list) or not claims:
        raise CkbError("reference review requires at least one source-grounded claim")
    lines = _source_lines(manifest)
    for index, claim in enumerate(claims):
        if not isinstance(claim, dict):
            raise CkbError(f"reference claim {index} must be an object")
        if not contains_chinese_narrative(claim.get("claim_zh")) or not contains_chinese_narrative(claim.get("evidence_note")):
            raise CkbError(f"reference claim {index} requires Chinese claim_zh and evidence_note")
        start = claim.get("start_line")
        end = claim.get("end_line")
        if not isinstance(start, int) or not isinstance(end, int) or start < 1 or end < start or end > len(lines):
            raise CkbError(f"reference claim {index} has an invalid inclusive line range")
        expected = "\n".join(lines[start - 1 : end]).strip()
        if not expected or str(claim.get("source_text") or "").strip() != expected:
            raise CkbError(f"reference claim {index} source_text does not exactly match the preserved line range")

def _source_uri(path: Path, line: int = 1) -> str:
    value = path.resolve().as_posix()
    return f"vscode://file/{quote(value, safe='/:')}:{line}:1"

def _active_reviewed(manifests: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return sorted(
        [item for item in manifests if item.get("status") == "agent-reviewed"],
        key=lambda item: (str(item["title"]).casefold(), str(item["reference_id"])),
    )

def _reference_sections(lines: list[str], source_type: str) -> list[dict[str, Any]]:
    if source_type == "text":
        result = []
        for start in range(0, len(lines), 80):
            content = "\n".join(lines[start : start + 80]).strip()
            if content:
                result.append({"heading": f"原文 {start + 1}–{min(len(lines), start + 80)} 行", "content": content, "start_line": start + 1, "end_line": min(len(lines), start + 80)})
        return result
    headings: list[tuple[int, str]] = []
    in_fence = False
    for index, line in enumerate(lines, start=1):
        if line.lstrip().startswith(("```", "~~~")):
            in_fence = not in_fence
        match = None if in_fence else re.match(r"^#{1,6}\s+(.+?)\s*$", line)
        if match:
            headings.append((index, match.group(1).strip()))
    if not headings:
        return _reference_sections(lines, "text")
    result = []
    for position, (start, heading) in enumerate(headings):
        end = headings[position + 1][0] - 1 if position + 1 < len(headings) else len(lines)
        content = "\n".join(lines[start - 1 : end]).strip()
        if content:
            result.append({"heading": heading, "content": content, "start_line": start, "end_line": end})
    return result

def list_references(output: Path, status: str = "all") -> dict[str, Any]:
    output = _validate_output(output)
    records = _manifests(output)
    if status != "all":
        records = [item for item in records if item.get("status") == status]
    return {
        "schema_version": 1,
        "status": "ready",
        "count": len(records),
        "records": [
            {key: item.get(key) for key in ("reference_id", "status", "title", "origin", "license", "revision", "supersedes", "human_file")}
            for item in records
        ],
    }

def _narrative(path: Path, label: str) -> str:
    if not path.is_file():
        raise CkbError(f"{label} file does not exist: {path}")
    value = re.sub(r"\s+", " ", path.read_text(encoding="utf-8-sig")).strip()
    if len(value) < 8 or len(value) > 600 or len(_CHINESE.findall(value)) < 4:
        raise CkbError(f"{label} must be one Simplified-Chinese statement between 8 and 600 characters")
    return value

def _evidence(output: Path, values: list[str], label: str) -> list[str]:
    if not values:
        raise CkbError(f"{label} requires at least one evidence path")
    if len(values) > 12:
        raise CkbError(f"{label} accepts at most 12 evidence paths")
    result: set[str] = set()
    for value in values:
        candidate = Path(value)
        if not candidate.is_absolute():
            candidate = output / candidate
        resolved = candidate.resolve()
        if not resolved.is_file() or not path_inside(resolved, output):
            raise CkbError(f"{label} evidence must be an existing file inside OUTPUT: {value}")
        result.add(resolved.relative_to(output).as_posix())
    return sorted(result)

def gap_records(output: Path) -> list[dict[str, Any]]:
    root = _records_root(output)
    if not root.is_dir():
        return []
    result = []
    for path in sorted(root.glob("gap-*.json")):
        value = json_load(path)
        if isinstance(value, dict):
            result.append(value)
    return result

def _index_value(records: list[dict[str, Any]]) -> dict[str, Any]:
    by_status = Counter(str(item.get("status")) for item in records)
    by_kind = Counter(str(item.get("kind")) for item in records)
    return {
        "schema_version": GAP_SCHEMA_VERSION,
        "status": "ready",
        "updated_at_utc": utc_now(),
        "counts": {"total": len(records), **{name: by_status.get(name, 0) for name in GAP_STATUSES}},
        "counts_by_kind": {name: by_kind.get(name, 0) for name in GAP_KINDS},
        "gaps": [
            {
                "gap_id": item["gap_id"], "kind": item["kind"], "status": item["status"],
                "summary_zh": item["summary_zh"], "evidence_count": len(item["evidence_paths"]),
                "updated_at_utc": item["updated_at_utc"],
            }
            for item in records
        ],
    }

def gap_navigation_counts(root: Path) -> dict[str, int] | None:
    path = root.parent / "workspace-meta/gaps/index.json"
    if not path.is_file():
        return None
    value = json_load(path)
    counts = value.get("counts") if isinstance(value, dict) else None
    if not isinstance(counts, dict):
        return None
    return {name: int(counts.get(name, 0)) for name in ("total", *GAP_STATUSES)}

def _sync_indexes(output: Path) -> None:
    if (output / "human").is_dir() and (output / "markdown").is_dir():
        from .work_record_index import refresh_work_record_index
        refresh_work_record_index(output)
    if (output / "agent-index.sqlite").is_file():
        from .agent_index import build_agent_index
        build_agent_index(output)
    if (output / "machine/knowledge.sqlite").is_file():
        from .machine_knowledge import build_machine_knowledge
        build_machine_knowledge(output)

def list_gaps(output: Path, status: str | None = None, kind: str | None = None) -> dict[str, Any]:
    if status is not None and status not in GAP_STATUSES:
        raise CkbError(f"gap status must be one of: {list(GAP_STATUSES)}")
    if kind is not None and kind not in GAP_KINDS:
        raise CkbError(f"gap kind must be one of: {list(GAP_KINDS)}")
    selected = [item for item in gap_records(output.resolve()) if (status is None or item.get("status") == status) and (kind is None or item.get("kind") == kind)]
    return {"schema_version": GAP_SCHEMA_VERSION, "status": "ready", "filters": {"status": status, "kind": kind}, "count": len(selected), "gaps": selected}

def gap_machine_records(output: Path) -> dict[str, Any]:
    records = gap_records(output)
    documents = []
    for item in records:
        status_zh = {"open": "待补证据", "deferred": "暂缓处理", "resolved": "已关闭"}[item["status"]]
        kind_zh = {"insufficient-evidence": "证据不足", "conflicting-sources": "来源冲突", "deferred-feedback": "暂缓反馈"}[item["kind"]]
        lines = [f"状态：{status_zh}", f"类型：{kind_zh}", f"待验证说明：{item['summary_zh']}", "证据路径：" + "；".join(item["evidence_paths"])]
        if item.get("resolution_zh"):
            lines.extend([f"关闭说明：{item['resolution_zh']}", "关闭证据：" + "；".join(item.get("resolution_evidence_paths", []))])
        content = "\n".join(lines)
        documents.append({"document_id": f"gap:{item['gap_id']}", "gap_id": item["gap_id"], "kind": "gap", "title": "研究缺口：" + item["summary_zh"][:80], "tag": "#类型/缺口", "human_file": None, "content": content, "section_heading": "待验证研究缺口" if item["status"] != "resolved" else "已关闭研究缺口", "record": item})
    return {"records": records, "documents": documents}

def _record_errors(output: Path, path: Path, item: dict[str, Any]) -> list[str]:
    if set(item) != _RECORD_FIELDS:
        return [f"{path.name}: fields differ from the fixed gap schema"]
    errors = []
    if item.get("schema_version") != GAP_SCHEMA_VERSION or item.get("kind") not in GAP_KINDS or item.get("status") not in GAP_STATUSES:
        errors.append(f"{path.name}: schema, kind, or status is invalid")
    summary = item.get("summary_zh")
    if not isinstance(summary, str) or len(_CHINESE.findall(summary)) < 4:
        errors.append(f"{path.name}: summary must use Simplified Chinese")
    evidence = item.get("evidence_paths")
    if not isinstance(evidence, list) or not evidence or len(evidence) > 12:
        errors.append(f"{path.name}: evidence_paths must contain one to twelve files")
    else:
        for value in evidence:
            relative = PurePosixPath(str(value))
            if relative.is_absolute() or ".." in relative.parts or not (output / Path(str(value))).is_file():
                errors.append(f"{path.name}: invalid or missing evidence path: {value}")
    expected_id = stable_id("gap", item.get("kind"), item.get("summary_zh"), *(item.get("evidence_paths") or []))
    if item.get("gap_id") != expected_id or path.stem != expected_id:
        errors.append(f"{path.name}: stable gap id mismatch")
    if item.get("status") == "resolved":
        resolution = item.get("resolution_zh")
        resolution_evidence = item.get("resolution_evidence_paths")
        if not isinstance(resolution, str) or len(_CHINESE.findall(resolution)) < 4:
            errors.append(f"{path.name}: resolved gap requires a Chinese resolution")
        if not isinstance(resolution_evidence, list) or not resolution_evidence:
            errors.append(f"{path.name}: resolved gap requires closure evidence")
        else:
            for value in resolution_evidence:
                relative = PurePosixPath(str(value))
                if relative.is_absolute() or ".." in relative.parts or not (output / Path(str(value))).is_file():
                    errors.append(f"{path.name}: invalid or missing closure evidence: {value}")
    elif item.get("resolution_zh") is not None or item.get("resolution_evidence_paths") != []:
        errors.append(f"{path.name}: unresolved gap must not contain resolution fields")
    return errors

def deploy(accept: bool) -> dict[str, Any]:
    plan = deployment_plan()
    if plan["status"] == "ready":
        return plan
    if plan["status"] != "permission-required":
        raise DependencyError(json.dumps(plan, ensure_ascii=False))
    if not accept:
        raise DependencyError(json.dumps(plan, ensure_ascii=False))
    payload = Path(plan["payload"])
    destination = Path(plan["destination"])
    destination.parent.mkdir(parents=True, exist_ok=True)
    temporary = destination.with_name(destination.name + ".deploying")
    if temporary.exists():
        safe_rmtree(temporary, destination.parent)
    temporary.mkdir()
    host_snapshot = _host_snapshot()
    with zipfile.ZipFile(payload) as archive:
        for member in archive.infolist():
            target = (temporary / member.filename).resolve()
            try:
                target.relative_to(temporary.resolve())
            except ValueError as exc:
                raise CkbError(f"runtime archive path escapes destination: {member.filename}") from exc
        archive.extractall(temporary)
    files_manifest_path = temporary / "payload-files.json"
    if not files_manifest_path.is_file():
        safe_rmtree(temporary, destination.parent)
        raise CkbError("runtime payload lacks payload-files.json")
    files_manifest = json_load(files_manifest_path)
    for item in files_manifest.get("files", []):
        member_path = (temporary / item["path"]).resolve()
        try:
            member_path.relative_to(temporary.resolve())
        except ValueError as exc:
            safe_rmtree(temporary, destination.parent)
            raise CkbError(f"runtime manifest path escapes destination: {item['path']}") from exc
        if not member_path.is_file() or member_path.stat().st_size != int(item["size"]) or sha256_file(member_path) != item["sha256"]:
            safe_rmtree(temporary, destination.parent)
            raise CkbError(f"runtime payload member verification failed: {item['path']}")
    json_write(
        temporary / "deployed.json",
        {
            "status": "ready",
            "lock_id": plan["lock_id"],
            "payload_sha256": plan["payload_sha256"],
            "deployed_at_utc": utc_now(),
            "host_snapshot_before": host_snapshot,
        },
    )
    if destination.exists():
        safe_rmtree(destination, destination.parent)
    os.replace(temporary, destination)
    plan["status"] = "ready"
    return plan

def remove(lock_id: str) -> dict[str, Any]:
    root = private_runtime_root().resolve()
    target = (root / lock_id).resolve()
    try:
        target.relative_to(root)
    except ValueError as exc:
        raise CkbError("runtime lock ID resolves outside the private runtime root") from exc
    existed = target.exists()
    deployment = json_load(target / "deployed.json") if (target / "deployed.json").is_file() else {}
    if existed:
        safe_rmtree(target, root)
    current_snapshot = _host_snapshot()
    expected_snapshot = deployment.get("host_snapshot_before")
    return {
        "status": "removed",
        "lock_id": lock_id,
        "path": str(target),
        "existed": existed,
        "host_snapshot_before": expected_snapshot,
        "host_snapshot_after": current_snapshot,
        "host_environment_restored": expected_snapshot is None or expected_snapshot == current_snapshot,
    }

def _host_snapshot() -> dict[str, Any]:
    commands = ["python", "node", "git", "pyright-langserver", "typescript-language-server", "clangd", "csharp-ls", "dotnet", "logseq"]
    return {"path": os.environ.get("PATH", ""), "commands": {name: shutil.which(name) for name in commands}}

def _parse_sample(value: str) -> tuple[str, Path]:
    if "=" not in value:
        raise CkbError(f"showcase sample must use LABEL=OUTPUT: {value}")
    label, raw = value.split("=", 1)
    label = re.sub(r"[^A-Za-z0-9._-]+", "-", label).strip("-.")
    if not label or not raw.strip():
        raise CkbError(f"showcase sample must use LABEL=OUTPUT: {value}")
    return label, Path(raw).resolve()

class SourceLinkRenderer:
    """Validate one opener config and cache resolved repository paths.

    Retrieval may render several entities from the same file.  The public
    one-shot helpers below intentionally preserve their old behavior, while a
    long-lived renderer avoids repeating Windows ``resolve`` and
    ``_getfinalpathname`` work for every candidate.
    """

    def __init__(self, config: dict[str, Any], *, trusted_relative_paths: bool = False) -> None:
        self.config = validate_local_openers(config)
        root_value = self.config.get("working_repo_root")
        if self.config.get("source_view") == "baseline" and self.config.get("baseline_snapshot_root"):
            root_value = self.config["baseline_snapshot_root"]
        self.root = Path(str(root_value)).resolve()
        self.trusted_relative_paths = trusted_relative_paths
        self._absolute_paths: dict[str, Path] = {}

    @property
    def cache_size(self) -> int:
        return len(self._absolute_paths)

    def absolute_path(self, relative_path: str) -> Path:
        cached = self._absolute_paths.get(relative_path)
        if cached is not None:
            return cached
        relative = PurePosixPath(relative_path)
        if relative.is_absolute() or ".." in relative.parts:
            raise CkbError(f"source path is outside the repository: {relative_path}")
        joined = self.root.joinpath(*relative.parts)
        if self.trusted_relative_paths:
            # Machine retrieval only supplies paths from the audited source
            # manifest.  Absolute and parent components were rejected above,
            # so the lexical path is repository-bounded without another
            # filesystem canonicalization for every selected entity.
            path = joined
        else:
            path = joined.resolve()
            if not path_inside(path, self.root):
                raise CkbError(f"source path is outside the selected source root: {relative_path}")
        self._absolute_paths[relative_path] = path
        return path

    def uri(self, relative_path: str, line: int, column: int = 1) -> str:
        absolute = self.absolute_path(relative_path)
        encoded = quote(absolute.as_posix(), safe="/:")
        editor = self.config["source_editor"]
        if editor == "vscode":
            return f"vscode://file/{encoded}:{int(line)}:{int(column)}"
        if editor == "vscode-insiders":
            return f"vscode-insiders://file/{encoded}:{int(line)}:{int(column)}"
        if editor == "file":
            prefix = "file:///" if os.name == "nt" else "file://"
            return prefix + encoded
        return str(self.config["custom_template"]).format(
            absolute_path=encoded,
            line=int(line),
            column=int(column),
        )

    def markdown_link(self, relative_path: str, start_line: int, end_line: int) -> str:
        uri = self.uri(relative_path, start_line, 1)
        label = f"打开源码：{relative_path} 第 {start_line} 行"
        suffix = f"  `{relative_path}:{start_line}-{end_line}`" if self.config.get("show_source_range", True) else ""
        return f"[{label}]({uri}){suffix}"

